// Checks the TypeScript rules port against the vectors generated by the Go
// engine (internal/engine/testdata/vectors.json). Run: npm run test:rules
import { readFileSync } from "node:fs";
import { CAPTURE_GOAL, LINE_LENGTH, NUM_CELLS, play, winningMoves, type Player, type State } from "../src/game/rules.ts";

interface VecState { cells: number[]; toMove: number; captured: number[]; winner: number; reason: number }
interface Vector { name: string; before: VecState; move: number; events: unknown[]; after: VecState }

const file = JSON.parse(readFileSync(new URL("../../internal/engine/testdata/vectors.json", import.meta.url), "utf8")) as {
  captureGoal: number; lineLength: number; vectors: Vector[];
};

let failures = 0;
if (file.captureGoal !== CAPTURE_GOAL || file.lineLength !== LINE_LENGTH) {
  console.error(`rule constants differ: Go goal=${file.captureGoal} line=${file.lineLength}, TS goal=${CAPTURE_GOAL} line=${LINE_LENGTH}`);
  failures++;
}
file.vectors.forEach((v, i) => {
  const s: State = {
    cells: v.before.cells.slice(), toMove: v.before.toMove as Player, captured: [v.before.captured[0], v.before.captured[1]],
    ply: 10, winner: v.before.winner, reason: v.before.reason,
  };
  if (s.cells.length !== NUM_CELLS) throw new Error("bad vector size");
  const { state, events } = play(s, v.move);
  const got = { cells: state.cells, toMove: state.toMove, captured: state.captured, winner: state.winner, reason: state.reason };
  const same = JSON.stringify(got) === JSON.stringify(v.after) && JSON.stringify(events) === JSON.stringify(v.events);
  if (!same) {
    failures++;
    console.error(`vector ${i} (${v.name}) differs\n  want ${JSON.stringify(v.after)} ${JSON.stringify(v.events)}\n  got  ${JSON.stringify(got)} ${JSON.stringify(events)}`);
  }
  // winningMoves must agree with actually playing every move.
  if (s.winner === 0) {
    const wins = new Set(winningMoves(s));
    for (let m = 0; m < NUM_CELLS; m++) {
      if (s.cells[m] !== 0) continue;
      const won = play(s, m).state.winner === s.toMove;
      if (won !== wins.has(m)) {
        failures++;
        console.error(`vector ${i}: winningMoves disagrees at ${m}`);
      }
    }
  }
});
if (failures) {
  console.error(`${failures} failure(s)`);
  process.exit(1);
}
console.log(`ok: ${file.vectors.length} shared rule vectors match the Go engine`);
